import os
import json
from pathlib import Path

# First, let's check what policy documents are available in the current directory
policy_files = []
for file in os.listdir('.'):
    if 'policy' in file.lower() and file.endswith(('.txt', '.json', '.md', '.pdf', '.doc', '.docx')):
        policy_files.append(file)

print("Found policy files:", policy_files)

# Let's read the content of each policy file
policies = {}
for file in policy_files:
    try:
        if file.endswith('.txt'):
            with open(file, 'r', encoding='utf-8') as f:
                policies[file] = f.read()
        elif file.endswith('.json'):
            with open(file, 'r', encoding='utf-8') as f:
                policies[file] = json.load(f)
        else:
            # For other formats, we'll just note the file type
            policies[file] = f"File format: {Path(file).suffix}"
    except Exception as e:
        policies[file] = f"Error reading file: {str(e)}"

# Display the content of each policy
print("\nPolicy contents:")
for file, content in policies.items():
    print(f"\n{'='*50}")
    print(f"File: {file}")
    print(f"{'='*50}")
    if isinstance(content, dict):
        print(json.dumps(content, indent=2))
    else:
        print(content[:500] + "..." if len(str(content)) > 500 else content)
